let visualGalleryState = {
  activeView: 'personas', // 'personas' | 'visual_gallery' | 'builder'
  activeCategory: 'all',
  searchQuery: '',
  selectedCase: null,
  activeLanguages: {} // { [caseId]: 'pt' | 'orig' }
};

function switchPromptsSubTab(tabName) {
  visualGalleryState.activeView = tabName;
  const container = document.getElementById('main-content-area');
  if (container && AppState.currentTab === 'prompts') {
    renderPromptsTab(container);
  }
}

function filterVisualGalleryCategory(categoryKey) {
  visualGalleryState.activeCategory = categoryKey;
  const container = document.getElementById('main-content-area');
  if (container && AppState.currentTab === 'prompts') {
    renderPromptsTab(container);
  }
}

function handleVisualGallerySearch(e) {
  visualGalleryState.searchQuery = (e.target.value || '').trim();
  const container = document.getElementById('main-content-area');
  if (container && AppState.currentTab === 'prompts') {
    renderPromptsTab(container);
  }
}

function toggleCaseLanguage(caseId, lang) {
  visualGalleryState.activeLanguages[caseId] = lang;
  const targetBox = document.getElementById('prompt-code-' + caseId);
  const item = AWESOME_GPT_IMAGE_CASES.find(c => c.id === caseId);
  if (targetBox && item) {
    targetBox.textContent = (lang === 'pt') ? (item.promptPT || item.prompt) : (item.promptOriginal || item.prompt);
  }
  
  // Update button active classes
  const btnPT = document.getElementById('btn-lang-pt-' + caseId);
  const btnOrig = document.getElementById('btn-lang-orig-' + caseId);
  if (btnPT && btnOrig) {
    if (lang === 'pt') {
      btnPT.className = 'btn btn-xs btn-primary bg-indigo-600 text-white fw-bold px-2 py-0.5 text-[10px] rounded-pill border-0 shadow-xs';
      btnOrig.className = 'btn btn-xs btn-light text-slate-500 px-2 py-0.5 text-[10px] rounded-pill border border-slate-200';
    } else {
      btnOrig.className = 'btn btn-xs btn-primary bg-indigo-600 text-white fw-bold px-2 py-0.5 text-[10px] rounded-pill border-0 shadow-xs';
      btnPT.className = 'btn btn-xs btn-light text-slate-500 px-2 py-0.5 text-[10px] rounded-pill border border-slate-200';
    }
  }
}

function copyVisualPromptCase(caseId) {
  const cases = typeof AWESOME_GPT_IMAGE_CASES !== 'undefined' ? AWESOME_GPT_IMAGE_CASES : [];
  const item = cases.find(c => c.id === caseId);
  if (!item) return;

  const currentLang = visualGalleryState.activeLanguages[caseId] || 'pt';
  const textToCopy = (currentLang === 'pt') ? (item.promptPT || item.prompt) : (item.promptOriginal || item.prompt);

  copyToClipboard(textToCopy, currentLang === 'pt' ? 'Prompt em Português (PT-BR) copiado!' : 'Prompt Original copiado!');
}

