function setModalPromptLanguage(caseId, lang) {
  const item = AWESOME_GPT_IMAGE_CASES.find(c => c.id === caseId);
  if (!item) return;

  const btnPT = document.getElementById('modal-btn-pt');
  const btnOrig = document.getElementById('modal-btn-orig');
  const output = document.getElementById('custom-vis-output');

  if (btnPT && btnOrig) {
    if (lang === 'pt') {
      btnPT.className = 'btn btn-sm btn-primary bg-indigo-600 text-white fw-bold px-3 py-1 text-xs';
      btnOrig.className = 'btn btn-sm btn-light text-slate-600 px-3 py-1 text-xs';
      if (output) output.value = item.promptPT || item.prompt;
    } else {
      btnOrig.className = 'btn btn-sm btn-primary bg-indigo-600 text-white fw-bold px-3 py-1 text-xs';
      btnPT.className = 'btn btn-sm btn-light text-slate-600 px-3 py-1 text-xs';
      if (output) output.value = item.promptOriginal || item.prompt;
    }
  }
}

function updateCustomVisualPrompt(caseId) {
  const item = AWESOME_GPT_IMAGE_CASES.find(c => c.id === caseId);
  if (!item) return;

  const subject = (document.getElementById('custom-vis-subject')?.value || '').trim();
  const brand = (document.getElementById('custom-vis-brand')?.value || '').trim();
  const location = (document.getElementById('custom-vis-location')?.value || '').trim();
  const lighting = document.getElementById('custom-vis-lighting')?.value || 'Luz natural suave de janela';

  const basePrompt = item.promptPT || item.prompt;

  let customPrompt = basePrompt;
  if (subject || brand) {
    customPrompt = `[CRIATIVO PERSONALIZADO PARA ${brand ? brand.toUpperCase() : 'MARCA'} - ${location.toUpperCase()}]
Produto/Tema: ${subject || item.title}
Iluminação: ${lighting}
Comando de Imagem IA:
${basePrompt}`;
  }

  const outputEl = document.getElementById('custom-vis-output');
  if (outputEl) outputEl.value = customPrompt;
}

function buildPromptFrom6Dimensions() {
  const subject = document.getElementById('p6-subject')?.value || 'Bolo artesanal de chocolate belga vulcão com morangos frescos';
  const style = document.getElementById('p6-style')?.value || 'Fotografia Publicitária Comercial 8K';
  const composition = document.getElementById('p6-comp')?.value || 'Close-up macro com calda escorrendo e ingredientes flutuando em gravidade zero';
  const lighting = document.getElementById('p6-light')?.value || 'Iluminação dramática de estúdio com luz de recorte suave';
  const colors = document.getElementById('p6-color')?.value || 'Tons quentes de chocolate, vermelho rubi dos morangos e acabamento brilhante';
  const params = document.getElementById('p6-params')?.value || 'Resolução 8K, renderização hiper-realista, foco nítido nos detalhes, sem distorção';

  const masterPrompt = `${style}. Sujeito: ${subject}. Composição: ${composition}. Iluminação: ${lighting}. Paleta de Cores: ${colors}. Especificações Técnicas: ${params}.`;
  
  const target = document.getElementById('p6-master-output');
  if (target) {
    target.value = masterPrompt;
    showToast('Prompt Mestre gerado em Português (PT-BR)!', 'success');
  }
}

function openVisualGalleryDirectly() {
  if (typeof visualGalleryState !== 'undefined') {
    visualGalleryState.activeView = 'visual_gallery';
  }
  if (typeof closeMobileSidebar === 'function') {
    try { closeMobileSidebar(); } catch(e) {}
  }
  if (typeof AppState !== 'undefined') {
    AppState.currentTab = 'prompts';
    if (typeof renderApp === 'function') renderApp();
  } else if (typeof switchTab === 'function') {
    switchTab('prompts');
  }
}

