if (typeof window !== 'undefined') {
  window.visualGalleryState = visualGalleryState;
  window.AWESOME_GPT_IMAGE_CASES = AWESOME_GPT_IMAGE_CASES;
  window.openVisualGalleryDirectly = openVisualGalleryDirectly;
  window.copyVisualPromptCase = copyVisualPromptCase;
  window.toggleCaseLanguage = toggleCaseLanguage;
  window.setModalPromptLanguage = setModalPromptLanguage;
  window.switchPromptsSubTab = switchPromptsSubTab;
  window.filterVisualGalleryCategory = filterVisualGalleryCategory;
  window.handleVisualGallerySearch = handleVisualGallerySearch;
  window.openCustomizeVisualPromptModal = openCustomizeVisualPromptModal;
  window.updateCustomVisualPrompt = updateCustomVisualPrompt;
  window.buildPromptFrom6Dimensions = buildPromptFrom6Dimensions;
}
